int traitSum(Object o, int x) {
  var sum = 0;
  if (o is Trait0) sum += o.trait0(x) + o.weight0(x / 3).round();
  if (o is Trait1) sum += o.trait1(x) + o.weight1(x / 3).round();
  if (o is Trait2) sum += o.trait2(x) + o.weight2(x / 3).round();
  if (o is Trait3) sum += o.trait3(x) + o.weight3(x / 3).round();
  if (o is Trait4) sum += o.trait4(x) + o.weight4(x / 3).round();
  if (o is Trait5) sum += o.trait5(x) + o.weight5(x / 3).round();
  if (o is Trait6) sum += o.trait6(x) + o.weight6(x / 3).round();
  if (o is Trait7) sum += o.trait7(x) + o.weight7(x / 3).round();
  if (o is Trait8) sum += o.trait8(x) + o.weight8(x / 3).round();
  if (o is Trait9) sum += o.trait9(x) + o.weight9(x / 3).round();
  if (o is Trait10) sum += o.trait10(x) + o.weight10(x / 3).round();
  if (o is Trait11) sum += o.trait11(x) + o.weight11(x / 3).round();
  return sum;
}

